window.kbPageData["views/entry/k-c753dbf8d5dec887"] = {"key":"entry/k-c753dbf8d5dec887","state":{"route":"entry/k-c753dbf8d5dec887"},"node":{"id":"k-c753dbf8d5dec887","mode":"k","title":"一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["观点与论证"],"出处性质":["公报解读正文"],"学科":["政治理论"],"时间索引":["年度事件或数据"],"来源主题":["二十届五中全会"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"党的二十届五中全会","slug":"6a94c2ad76dd"}],"directorySummary":"（六）一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本\n方针。\n必须牢记党除了工人阶级和最广大人民群众的利益没有自己特殊的利益、党同腐\n败水火不容，坚定走好中国特色反腐败之路①，加强党中央对反腐败工作的集中统一领\n导，更加注重标本兼治、系统施治，坚持从严惩、精准治、有效防、一体抓…","sources":[{"id":"fb0f94ee065b8e4b","label":"一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本","topic":"二十届五中全会","category":"时政","text":"（六）一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本\n方针。\n必须牢记党除了工人阶级和最广大人民群众的利益没有自己特殊的利益、党同腐\n败水火不容，坚定走好中国特色反腐败之路①，加强党中央对反腐败工作的集中统一领\n导，更加注重标本兼治、系统施治，坚持从严惩、精准治、有效防、一体抓，将反腐\n败斗争进行到底。①要保持惩治腐败高压态势，②加强对权力运行的制约和监督，③\n夯实崇廉拒腐思想根基，④增强一体推进不敢腐不能腐不想腐②综合效能。","source":{"doc":"41195a191a57c1c36332","first":18,"last":18,"page":18,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"公报解读正文"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-c753dbf8d5dec887":[]}};
